import express from 'express'
const app = express()
app.use(express.json())

const users = new Map()

app.post('/users', (req, res) => {
  const { name } = req.body ?? {}
  if (!name) return res.status(400).json({ error: 'name is required' })

  const id = users.size + 1
  users.set(id, { id, name })
  res.status(201).location(`/users/${id}`).json(users.get(id))
})

app.get('/users/:id', (req, res) => {
  const user = users.get(Number(req.params.id))
  if (!user) return res.sendStatus(404)          // body: "Not Found"
  res.set('Cache-Control', 'no-store').json(user)
})

app.delete('/users/:id', (req, res) => {
  users.delete(Number(req.params.id))
  res.status(204).end()                          // no body
})

app.listen(3000)

import express from 'express'
import path from 'node:path'

const app = express()
const filesDir = path.join(import.meta.dirname, 'files')

app.get('/old-page', (req, res) => res.redirect(301, '/new-page'))
app.get('/new-page', (req, res) => res.send('I am the new page'))

app.get('/files/:name', (req, res, next) => {
  // root blocks ../ traversal; dotfiles are denied
  res.sendFile(req.params.name, { root: filesDir, dotfiles: 'deny' }, (err) => {
    if (err) next(err)           // 404 if the file does not exist
  })
})

app.get('/download/report', (req, res) => {
  res.download(path.join(filesDir, 'report.pdf'), 'Monthly-Report.pdf')
})

app.listen(3000)

import express from 'express'
import cookieParser from 'cookie-parser'

const app = express()
app.disable('x-powered-by')
app.use(cookieParser('my-cookie-secret'))

app.get('/set-theme/:name', (req, res) => {
  res.cookie('theme', req.params.name, {
    httpOnly: true, sameSite: 'lax', maxAge: 7 * 24 * 60 * 60 * 1000,
  })
  res.cookie('visitor', 'abc123', { signed: true })
  res.send('cookie set')
})

app.get('/theme', (req, res) => {
  res.json({ theme: req.cookies.theme ?? 'light', visitor: req.signedCookies.visitor })
})

app.get('/report', (req, res) => {
  res.format({
    'text/plain': () => res.send('Total: 42'),
    'application/json': () => res.json({ total: 42 }),
    'text/html': () => res.send('<b>Total: 42</b>'),
    default: () => res.status(406).send('Not Acceptable'),
  })
})

app.listen(3000)

import express from 'express'
import compression from 'compression'
import fs from 'node:fs'
import { pipeline } from 'node:stream/promises'

const app = express()
app.use(compression())

// stream a large file
app.get('/export.csv', async (req, res) => {
  res.type('text/csv').attachment('export.csv')
  await pipeline(fs.createReadStream('export.csv'), res)
})

// cache headers for a public, rarely-changing API response
app.get('/api/countries', (req, res) => {
  res.set('Cache-Control', 'public, max-age=3600')
  res.json(['India', 'Japan', 'Brazil'])
})

// never cache private data
app.get('/api/me', (req, res) => {
  res.set('Cache-Control', 'no-store')
  res.json({ id: 1 })
})

app.listen(3000)
